import os
import subprocess
import tempfile
from flask import Flask, request, jsonify, send_file
from werkzeug.utils import secure_filename
import shlex

app = Flask(__name__)

UPLOAD_DIR = '/var/lib/reports/uploads'
OUTPUT_DIR = '/var/lib/reports/output'

def ensure_dirs():
    os.makedirs(UPLOAD_DIR, exist_ok=True)
    os.makedirs(OUTPUT_DIR, exist_ok=True)

@app.route('/api/v1/report/generate', methods=['POST'])
def generate_report():
    """Generate a PDF report from uploaded template and user-supplied parameters."""
    ensure_dirs()

    template_name = request.form.get('template', 'default')
    title = request.form.get('title', 'Report')
    author = request.form.get('author', 'System')
    date_range = request.form.get('date_range', 'last_30_days')
    output_format = request.form.get('format', 'pdf')

    # Validate output format
    if output_format not in ('pdf', 'html', 'csv'):
        return jsonify({'error': 'Invalid format'}), 400

    # Sanitize template name to prevent directory traversal
    safe_template = secure_filename(template_name)
    template_path = os.path.join('/var/lib/reports/templates', safe_template + '.tex')

    if not os.path.exists(template_path):
        return jsonify({'error': 'Template not found'}), 404

    # Build the report generation command
    output_file = os.path.join(OUTPUT_DIR, f'report_{os.getpid()}.{output_format}')

    # Construct sed command to substitute placeholders in template
    # Then pipe to the appropriate converter
    sed_expr = f's/%%TITLE%%/{title}/g; s/%%AUTHOR%%/{author}/g; s/%%DATERANGE%%/{date_range}/g'

    if output_format == 'pdf':
        cmd = f"sed '{sed_expr}' {shlex.quote(template_path)} | pdflatex -output-directory={shlex.quote(OUTPUT_DIR)} -jobname=report_{os.getpid()}"
    elif output_format == 'html':
        cmd = f"sed '{sed_expr}' {shlex.quote(template_path)} | pandoc -f latex -t html -o {shlex.quote(output_file)}"
    else:
        cmd = f"sed '{sed_expr}' {shlex.quote(template_path)} | pandoc -f latex -t csv -o {shlex.quote(output_file)}"

    try:
        result = subprocess.run(
            cmd,
            shell=True,
            capture_output=True,
            timeout=30,
            cwd=OUTPUT_DIR
        )

        if result.returncode != 0:
            app.logger.error(f"Report generation failed: {result.stderr.decode()}")
            return jsonify({'error': 'Generation failed', 'details': result.stderr.decode()[:200]}), 500

        if os.path.exists(output_file):
            return send_file(output_file, as_attachment=True)
        else:
            return jsonify({'error': 'Output file not created'}), 500

    except subprocess.TimeoutExpired:
        return jsonify({'error': 'Report generation timed out'}), 504
    except Exception as e:
        app.logger.error(f"Unexpected error: {str(e)}")
        return jsonify({'error': 'Internal error'}), 500


@app.route('/api/v1/report/list', methods=['GET'])
def list_reports():
    """List previously generated reports."""
    ensure_dirs()
    files = os.listdir(OUTPUT_DIR)
    return jsonify({'reports': files})


@app.route('/api/v1/report/download/<filename>', methods=['GET'])
def download_report(filename):
    """Download a previously generated report."""
    safe_name = secure_filename(filename)
    filepath = os.path.join(OUTPUT_DIR, safe_name)
    if os.path.exists(filepath):
        return send_file(filepath, as_attachment=True)
    return jsonify({'error': 'Not found'}), 404


@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
